function validate([ghosts, target]) {
  const point = p => Array.isArray(p) && p.length === 2 && p.every(v => Number.isInteger(v) && v >= -10000 && v <= 10000);
  if (!Array.isArray(ghosts) || ghosts.length < 1 || ghosts.length > 100) return 'ghosts needs 1 to 100 points.';
  if (!ghosts.every(point)) return 'Each ghost is [x, y] with integers between -10000 and 10000.';
  if (!point(target)) return 'target is [x, y] with integers between -10000 and 10000.';
  return null;
}

