function escapeGhosts(ghosts, target) {
  const [targetX, targetY] = target;
  const myDistance = Math.abs(targetX) + Math.abs(targetY);

  for (const [ghostX, ghostY] of ghosts) {
    const ghostDistance = Math.abs(ghostX - targetX) + Math.abs(ghostY - targetY);
    if (ghostDistance <= myDistance) {
      return false;
    }
  }
  return true;
}

