function escapeGhosts(ghosts, target) {
  // Walk to the target along x first, then y; a ghost can stand on a point at time t when it is at most t steps away.
  const caught = (x, y, t) => ghosts.some(([gx, gy]) => Math.abs(gx - x) + Math.abs(gy - y) <= t);
  let x = 0, y = 0, t = 0;
  if (caught(x, y, t)) return false;
  while (x !== target[0] || y !== target[1]) {
    if (x !== target[0]) x += Math.sign(target[0] - x);
    else y += Math.sign(target[1] - y);
    t++;
    if (caught(x, y, t)) return false;
  }
  return true;
}

