function generate(rand, size) {
  const pick = (limit) => Math.floor(rand() * (2 * limit + 1)) - limit;
  if (size === 'small') {
    const count = 1 + Math.floor(rand() * 4);
    const ghosts = Array.from({ length: count }, () => [pick(5), pick(5)]);
    if (rand() < 0.2) ghosts.push([...ghosts[0]]);
    return [ghosts, [pick(4), pick(4)]];
  }
  // Large: 100 ghosts; half the time they are kept far from a target near the start so escapes happen too.
  const target = [pick(10000), pick(10000)];
  const far = rand() < 0.5;
  if (far) { target[0] = pick(2000); target[1] = pick(2000); }
  const ghosts = Array.from({ length: 100 }, () => {
    if (!far) return [pick(10000), pick(10000)];
    const x = 6000 + Math.floor(rand() * 4001), y = 6000 + Math.floor(rand() * 4001);
    return [rand() < 0.5 ? x : -x, rand() < 0.5 ? y : -y];
  });
  return [ghosts, target];
}
